-- MariaDB specific: SEQUENCE, RETURNING, INTERSECT/EXCEPT, system versioning, invisible columns, JSON_TABLE
CREATE SEQUENCE IF NOT EXISTS seq_invoice START WITH 1000 INCREMENT BY 1 MINVALUE 1 MAXVALUE 99999999 CACHE 100 NOCYCLE;
CREATE OR REPLACE SEQUENCE seq_ticket START WITH 1 INCREMENT BY 5 CYCLE;
CREATE SEQUENCE seq_simple;
ALTER SEQUENCE seq_invoice RESTART WITH 5000;
ALTER SEQUENCE IF EXISTS seq_invoice INCREMENT BY 10;
DROP SEQUENCE IF EXISTS seq_ticket;
SELECT NEXT VALUE FOR seq_invoice;
SELECT NEXTVAL(seq_invoice), LASTVAL(seq_invoice);
SELECT SETVAL(seq_invoice, 7000);
INSERT INTO invoices (id, amount) VALUES (NEXT VALUE FOR seq_invoice, 99.50);
INSERT INTO invoices (id, amount) VALUES (NEXTVAL(seq_invoice), 10);
CREATE TABLE IF NOT EXISTS tickets (id BIGINT NOT NULL DEFAULT NEXT VALUE FOR seq_ticket PRIMARY KEY, title VARCHAR(100));
INSERT INTO users (email, name) VALUES ('r@example.com', 'R') RETURNING id, created_at;
INSERT INTO users (email, name) VALUES ('s@example.com', 'S'), ('t@example.com', 'T') RETURNING *;
INSERT INTO users (email, name) SELECT email, name FROM staging_users RETURNING id AS new_id, email;
DELETE FROM sessions WHERE expires_at < NOW() RETURNING id, user_id;
DELETE FROM carts WHERE user_id = 5 RETURNING *;
REPLACE INTO settings (k, v) VALUES ('a', '1') RETURNING k, v;
INSERT INTO page_views (page_id, views) VALUES (1, 1) ON DUPLICATE KEY UPDATE views = views + 1 RETURNING page_id, views;
SELECT id FROM t1 INTERSECT SELECT id FROM t2;
SELECT id FROM t1 EXCEPT SELECT id FROM t2;
SELECT id FROM t1 INTERSECT ALL SELECT id FROM t2;
SELECT id FROM t1 EXCEPT ALL SELECT id FROM t2;
(SELECT id FROM t1 UNION SELECT id FROM t2) INTERSECT SELECT id FROM t3;
SELECT id FROM t1 UNION SELECT id FROM t2 EXCEPT SELECT id FROM t3 ORDER BY id;
SELECT user_id FROM orders WHERE status = 'paid' INTERSECT SELECT user_id FROM orders WHERE status = 'shipped' EXCEPT SELECT user_id FROM bans;
CREATE TABLE IF NOT EXISTS accounts (id INT PRIMARY KEY, balance DECIMAL(12, 2) NOT NULL) WITH SYSTEM VERSIONING;
CREATE TABLE IF NOT EXISTS prices (id INT PRIMARY KEY, price DECIMAL(10, 2), row_start TIMESTAMP(6) GENERATED ALWAYS AS ROW START, row_end TIMESTAMP(6) GENERATED ALWAYS AS ROW END, PERIOD FOR SYSTEM_TIME (row_start, row_end)) WITH SYSTEM VERSIONING;
CREATE TABLE IF NOT EXISTS hist (id INT, v INT) WITH SYSTEM VERSIONING PARTITION BY SYSTEM_TIME INTERVAL 1 MONTH (PARTITION p_old HISTORY, PARTITION p_cur CURRENT);
ALTER TABLE users ADD SYSTEM VERSIONING;
ALTER TABLE users DROP SYSTEM VERSIONING;
ALTER TABLE users ADD COLUMN IF NOT EXISTS secret VARCHAR(64) INVISIBLE;
CREATE TABLE IF NOT EXISTS inv (id INT PRIMARY KEY, a INT, hidden_note TEXT INVISIBLE);
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_hash CHAR(32) WITHOUT SYSTEM VERSIONING;
SELECT * FROM accounts FOR SYSTEM_TIME AS OF TIMESTAMP '2025-01-01 00:00:00' WHERE id = 1;
SELECT * FROM accounts FOR SYSTEM_TIME BETWEEN '2025-01-01' AND '2025-06-30' WHERE id = 1;
SELECT * FROM accounts FOR SYSTEM_TIME FROM '2025-01-01' TO '2025-02-01';
SELECT * FROM accounts FOR SYSTEM_TIME ALL ORDER BY id;
SELECT id, ROW_START, ROW_END FROM accounts FOR SYSTEM_TIME ALL WHERE id = 1;
DELETE HISTORY FROM accounts BEFORE SYSTEM_TIME '2024-01-01 00:00:00';
SELECT jt.* FROM JSON_TABLE('[{"a":1,"b":"x"},{"a":2,"b":"y"}]', '$[*]' COLUMNS (a INT PATH '$.a', b VARCHAR(10) PATH '$.b')) AS jt;
SELECT o.id, jt.sku, jt.qty FROM orders o, JSON_TABLE(o.items, '$[*]' COLUMNS (rn FOR ORDINALITY, sku VARCHAR(32) PATH '$.sku', qty INT PATH '$.qty' DEFAULT '1' ON EMPTY)) AS jt;
SELECT JSON_EXTRACT(payload, '$.user.id') AS uid, JSON_UNQUOTE(JSON_EXTRACT(payload, '$.name')) FROM audit_log;
SELECT JSON_VALUE(payload, '$.name') AS n, JSON_QUERY(payload, '$.tags') AS t FROM audit_log WHERE JSON_VALID(payload);
SELECT JSON_OBJECT('id', id, 'email', email) FROM users;
SELECT JSON_ARRAYAGG(email), JSON_OBJECTAGG(id, email) FROM users;
SELECT JSON_SET(payload, '$.seen', TRUE), JSON_ARRAY_APPEND(payload, '$.tags', 'x') FROM audit_log;
SELECT * FROM audit_log WHERE JSON_CONTAINS(payload, '"x"', '$.tags') AND JSON_LENGTH(payload) > 1;
SELECT UUID(), UUID_SHORT();
CREATE TABLE IF NOT EXISTS things (id UUID NOT NULL DEFAULT UUID() PRIMARY KEY, addr INET6, ip4 INET4);
SELECT SYS_GUID();
SELECT id, COLUMN_GET(dyn, 'k' AS CHAR) FROM dyn_t;
SELECT REGEXP_REPLACE(name, '[0-9]+', '#'), REGEXP_SUBSTR(name, '[a-z]+'), REGEXP_INSTR(name, 'x') FROM users;
SELECT LEFT(name, 3), RIGHT(name, 2), SUBSTRING_INDEX(email, '@', -1), TRIM(BOTH ' ' FROM name), LPAD(id, 8, '0') FROM users;
SELECT DATE_FORMAT(NOW(), '%Y-%m-%d'), STR_TO_DATE('2025-01-02', '%Y-%m-%d'), UNIX_TIMESTAMP(), FROM_UNIXTIME(0);
SELECT * FROM information_schema.tables WHERE table_schema = DATABASE();
SELECT * FROM mysql.user LIMIT 1;
SET STATEMENT max_statement_time = 5 FOR SELECT * FROM orders;
SELECT * FROM orders ORDER BY id LIMIT 10 OFFSET 5 ROWS EXAMINED 1000;
SELECT * FROM orders FETCH FIRST 5 ROWS ONLY;
SELECT * FROM orders ORDER BY id OFFSET 10 ROWS FETCH NEXT 5 ROWS ONLY;
SELECT * FROM orders ORDER BY id FETCH FIRST 3 ROWS WITH TIES;
SELECT id FROM orders WHERE id > 5 LIMIT 5, 10;
SELECT * FROM t1 FOR UPDATE WAIT 5;
SELECT * FROM t1 FOR UPDATE NOWAIT;
CREATE ROLE IF NOT EXISTS reporting;
GRANT SELECT ON shop.* TO reporting;
SET ROLE reporting;
BACKUP STAGE START;
BACKUP STAGE END;
